public class ArchiveUtils_sanitize_TriageGen0Test {



    @Test
    public void testSanitize_ISOControlCharacters() {
        // Tests characters where Character.isISOControl(c) is true (e.g., \n, \t, \r)
        String input = "A\nB\tC\rD";
        String expected = "A?B?C?D";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }










