public class ArchiveUtils_sanitize_TriageGen0Test {







    @Test
    public void testSanitize_NullUnicodeBlock() {
        // Character.UnicodeBlock.of(c) can return null for some unassigned characters
        // \uFFFF is often unassigned/null block
        String input = "\uFFFF";
        String expected = "?";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }






}

