import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ArchiveUtils_sanitize_TriageGen0Test {











    @Test
    public void testSanitize_MixedContent() {
        // Mix of valid, control, and potentially null-block characters
        // \u0001 is ISO control
        // \u0041 is 'A' (Basic Latin)
        // \uFFFF is Null Block
        String input = "A\u0001B\uFFFF";
        String expected = "A?B?";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }


}

package org.apache.commons.compress.utils;

