import static org.junit.Assert.assertEquals;

public class ArchiveUtils_sanitize_TriageGen0Test {













    @Test
    public void testSanitize_UnicodeCharacters() {
        // Test characters from other blocks (e.g., Greek or Cyrillic)
        // 'Ω' is GREEK block
        String input = "Ω";
        String expected = "Ω";
        assertEquals(expected, ArchiveUtils.sanitize(input));

        // 'Д' is CYRILLIC block
        String input2 = "Д";
        String expected2 = "Д";
        assertEquals(expected2, ArchiveUtils.sanitize(input2));
    }
}
